-- State electricity tariffs: slabs, free units, duty - read from https://electricbill.in/en/tariffs (one page per state, each citing
-- the regulator's order) and, for the free-unit schemes, from news reports of the government orders. EVERY row is "indicative":
-- the figures are as that site lists them and have NOT been checked against the order itself, and the site contradicts itself in
-- places (duty, meter rent, a headline rate that fits only the lifeline category). Each row's note names the order it cites and the
-- inconsistencies seen. The admin app's Electricity rates page is where a row is replaced by one checked against the order and
-- marked verified.
--
-- Left out because no usable source was found: Bihar, Goa, Punjab, Meghalaya, Mizoram, Nagaland, Sikkim, Ladakh, Lakshadweep,
-- Dadra and Nagar Haveli and Daman and Diu. A customer there keeps using the rate set on their own account.
--
-- This replaces the first flat 'indicative' rates (midpoints of ranges quoted by aggregator sites) that were only a placeholder.

delete from waytara.electricity_tariffs where confidence = 'indicative' and source_url not like 'https://electricbill.in/%';

on conflict (state, category, effective_from) do nothing;

-- Record every rate that is already in force as an already-announced change, so the daily job does not e-mail customers about rates
-- that were simply loaded today (it tells people about a change that comes AFTER these).
select t.id, t.state, t.category,
       lag(t.rate_per_kwh) over (partition by t.state, t.category order by t.effective_from),
       t.rate_per_kwh, t.effective_from, now()
from waytara.electricity_tariffs t
where t.effective_from <= current_date
on conflict (tariff_id) do nothing;
